const inside=views.get('inside').view;
inside.innerHTML='<div class="film-production-head"><div><span class="eyebrow">THE WORKING PIPELINE</span><h2>One evidence record.<br>Every screen.</h2><p>Watch, review, personalize and publish from the same film and playhead.</p></div><button class="red-button" id="film-output">Open live output ↗</button></div><div class="film-pipeline"></div><div class="film-deliverables"><div><span class="eyebrow">YOUR CURRENT OUTPUT</span><h3></h3><p></p><button class="outline-button">Export this evidence ↓</button></div><details><summary>Inspect the current cue and evidence</summary><pre></pre></details></div><div class="film-requirements"><article><span class="eyebrow">SYNTHETIC FOOTBALL DATA</span><h3>Need the full-match pipeline?</h3><p>Choose “Synthetic match / data replay” above for coordinate-based passing, tracking, player focus and correction tests. Run a seeded 90-minute fixture through Azure for live events and a full-time AI recap.</p><button class="outline-button" id="film-full-match">Run the full-match generator ↗</button></article><article><span class="eyebrow">WHAT IS VERIFIED</span><h3>Evidence before spectacle.</h3><p>The film uses reviewed observations. Synthetic scenarios provide computed measurements. Three presenters use Azure AI; Vector calculates and Check applies evidence rules. All five have distinct public roles.</p><p>Truth Lab also checks actual frames with Azure vision; candidates remain unverified. Continuous player tracking, calibrated pixel measurements, Fabric integration and a rendering-partner connection are not implemented.</p></article></div>';
const stages=[['01','Ingest','Reviewed film markers enter as the playhead reaches them.'],['02','Interpret','Source and timestamp stay attached to every observation.'],['03','Explain','Observe → teach → calculate → challenge → synthesize.'],['04','Render','Azure streams expiring cues to a separate browser or OBS.'],['05','Personalize','Fan, beginner, math, tactical and player views. Three languages.']];
