 if(s.section==='inside'){view.querySelector('.film-deliverables h3').textContent=p.title;view.querySelector('.film-deliverables p').textContent=p.body;view.querySelector('pre').textContent=JSON.stringify(pitchsideExport(input(s)),null,2);return;}
